#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.."&&pwd)";. "$ROOT/scripts/tests/fair_launch_local_e2e_test_cleanup.sh";S="$(jc_fl_test_root_create JC_FL_TEST_LIFECYCLE_REMOVAL_V1)";ACTIVE=''
fail(){ echo "lifecycle_removal_test: FAIL: $*" >&2;exit 1;}
cleanup(){ local original=$? ok=1;set +e;[ -z "$ACTIVE" ]||jc_fl_test_run_cleanup "$ACTIVE"||ok=0;[ "$ok" != 1 ]||jc_fl_test_root_finalize "$S"||ok=0;[ "$ok" = 1 ]||echo "lifecycle_removal_test: retained root=$S active=${ACTIVE:-none}" >&2;[ "$original" -ne 0 ]&&return "$original";[ "$ok" = 1 ];};trap cleanup EXIT
# Replacement-source rm failure retains exact original ID and evidence, then exact authority recovers it.
for inject in rm post;do
 args=();[ "$inject" = rm ]&&args+=(JC_FL_E2E_TEST_LIFECYCLE_DOCKER_RM_FAIL=1)||args+=(JC_FL_E2E_TEST_LIFECYCLE_POST_RM_QUERY_FAIL=1)
 set +e;env JC_FL_E2E_STATE_ROOT="$S" JC_FL_E2E_TEST_REPLACE_CONTAINER=privileged "${args[@]}" bash "$ROOT/scripts/fair-launch/local-e2e/start.sh">"$S/replacement-$inject.out" 2>&1;rc=$?;set -e;[ "$rc" -ne 0 ]||fail "replacement-$inject rc";ACTIVE="$(find "$S" -mindepth 1 -maxdepth 1 -type d|head -1)";[ -n "$ACTIVE" ]&&[ -f "$ACTIVE/evidence/start-failure.json" ]||fail "replacement-$inject retained";source="$ACTIVE/evidence/replacement-source-removal.json.source.json";removal="${source}.removal.json";[ "$(stat -Lc '%a' "$source" "$removal" "$ACTIVE/evidence/replacement-source-removal.json.rm-output")" = $'600\n600\n600' ]||fail "replacement-$inject transaction modes";if [ "$inject" = rm ];then [ "$(python3 "$JC_FL_TEST_CLEANUP_PY" removal-stage "$removal" "$source")" = AUTHORIZED_BEFORE_RM ]||fail "replacement-rm stage";else [ "$(python3 "$JC_FL_TEST_CLEANUP_PY" removal-stage "$removal" "$source")" = RM_SUCCEEDED_QUERY_PENDING ]||fail "replacement-post stage";[ "$(stat -Lc '%a' "$ACTIVE/evidence/replacement-source-removal.json.source.json.post-rm-query.raw")" = 600 ]||fail "replacement-post query mode";fi;jc_fl_test_run_cleanup "$ACTIVE"||fail "replacement-$inject recovery";ACTIVE=''
done
# Normal teardown rm/post-query failures retain exact state/evidence; cleanup recovers by exact ID.
for inject in rm post;do
 out="$(JC_FL_E2E_STATE_ROOT="$S" bash "$ROOT/scripts/fair-launch/local-e2e/start.sh")";run="$(printf '%s\n' "$out"|sed -n 's/^RUN_ID=//p')";ACTIVE="$S/$run";set +e;if [ "$inject" = rm ];then JC_FL_E2E_STATE_ROOT="$S" JC_FL_E2E_TEST_LIFECYCLE_DOCKER_RM_FAIL=1 bash "$ROOT/scripts/fair-launch/local-e2e/teardown.sh" "$run">"$S/teardown-$inject.out" 2>&1;else JC_FL_E2E_STATE_ROOT="$S" JC_FL_E2E_TEST_LIFECYCLE_POST_RM_QUERY_FAIL=1 bash "$ROOT/scripts/fair-launch/local-e2e/teardown.sh" "$run">"$S/teardown-$inject.out" 2>&1;fi;rc=$?;set -e;[ "$rc" -ne 0 ]&&[ -f "$ACTIVE/evidence/teardown-failure.json" ]||fail "teardown-$inject retained";source="$ACTIVE/evidence/teardown-container-removal.json.source.json";removal="${source}.removal.json";[ "$(stat -Lc '%a' "$source" "$removal" "$ACTIVE/evidence/teardown-container-removal.json.rm-output")" = $'600\n600\n600' ]||fail "teardown-$inject transaction modes";if [ "$inject" = rm ];then [ "$(python3 "$JC_FL_TEST_CLEANUP_PY" removal-stage "$removal" "$source")" = AUTHORIZED_BEFORE_RM ]||fail "teardown-rm stage";else [ "$(python3 "$JC_FL_TEST_CLEANUP_PY" removal-stage "$removal" "$source")" = RM_SUCCEEDED_QUERY_PENDING ]||fail "teardown-post stage";[ "$(stat -Lc '%a' "$ACTIVE/evidence/teardown-container-removal.json.source.json.post-rm-query.raw")" = 600 ]||fail "teardown-post query mode";fi;jc_fl_test_run_cleanup "$ACTIVE"||fail "teardown-$inject recovery";ACTIVE=''
done
jc_fl_test_root_finalize "$S";trap - EXIT
echo 'fair_launch_local_e2e_lifecycle_removal_test: PASS replacement and normal teardown rm/post-query retention and exact recovery'
